403				t.Fatalf("rollback failed state must reopen: %v", err)
404			}
405			defer s2.Close()
406			cv := mustGetCampaign(s2, spec.ID)
407			if findDevice(cv, "d1").Status != DeviceRollbackFailed || len(cv.Results) != 3 {
408				t.Fatalf("view: %+v", cv.Results)
