549	// 仅时区表示不同（Z vs +08:00）时不得判为冲突。
550	func TestResultHistoryTimezoneEqualInstant(t *testing.T) {
551		_, dir, _ := setupReady(t)
552		// 下载结果接受于 12:01:00Z，改写为 +08:00 表示的同一时刻 20:01:00+08:00。
553		rewriteStoreBytes(t, dir, func(doc map[string]any) {
554			resultDocs(doc, "cmp-1")[0]["at"] = "2026-10-02T20:01:00+08:00"
555		})
556		s, err := Open(dir)
557		if err != nil {
558			t.Fatalf("same instant in different zone must open: %v", err)
559		}
560		defer s.Close()
561		cv := mustGetCampaign(s, "cmp-1")
562		want := upBase.Add(time.Minute)
563		if !cv.Results[0].At.Equal(want) {
564			t.Fatalf("restored time %v not equal to %v", cv.Results[0].At, want)
565		}
566	}
567	
568	// TestResultHistoryPreservesOrderAndContent 合法数据按原样打开：
569	// 设备进度、结果内容与接受顺序不变。
570	func TestResultHistoryPreservesOrderAndContent(t *testing.T) {
571		s := setupUpgrade(t, "d1", "d2")
572		spec := upSpec()
573		spec.BatchSize = 2
574		spec.Devices = []string{"d1", "d2"}
575		createCampaign(t, s, spec)
576		bringOnline(t, s, "d1")
577		bringOnline(t, s, "d2")
578		finishDevice(t, s, spec, "d1", upBase)
579		finishDevice(t, s, spec, "d2", upBase.Add(10*time.Minute))
580		cv0 := mustGetCampaign(s, spec.ID)
581		dir := s.dir
582		s.Close()
583	
584		s2, err := Open(dir)
585		if err != nil {
586			t.Fatalf("valid history must reopen: %v", err)
587		}
588		defer s2.Close()
589		cv := mustGetCampaign(s2, spec.ID)
590		if cv.Status != CampaignSucceeded || len(cv.Results) != len(cv0.Results) {
591			t.Fatalf("restored campaign: status=%s results=%+v", cv.Status, cv.Results)
592		}
593		for i := range cv0.Results {
