222	// CreateCampaign 创建分批升级活动。任何必填信息缺失、设备或目标版本未登记、
223	// 设备当前版本不兼容或设备已参加未结束活动时，整次创建失败，不留下部分记录。
224	func (s *Store) CreateCampaign(spec CampaignSpec) error {
225		s.mu.Lock()
226		defer s.mu.Unlock()
227		if err := s.checkOpen(); err != nil {
228			return err
229		}
230		// 先做全部校验，全部通过后才写入，保证原子创建。
231		if spec.ID == "" {
232			return ErrInvalidCampaignID
233		}
234		if spec.Operator == "" {
235			return ErrInvalidOperator
236		}
237		if spec.CreatedAt.IsZero() {
238			return fmt.Errorf("%w: created at", ErrInvalidTime)
239		}
240		if spec.WindowStart.IsZero() || spec.WindowEnd.IsZero() {
241			return fmt.Errorf("%w: maintenance window", ErrInvalidTime)
242		}
243		if spec.Deadline.IsZero() {
244			return fmt.Errorf("%w: deadline", ErrInvalidTime)
245		}
246		if len(spec.Devices) == 0 {
247			return ErrInvalidDeviceList
248		}
249		seen := make(map[string]bool, len(spec.Devices))
250		for _, id := range spec.Devices {
251			if id == "" {
252				return ErrInvalidDeviceID
253			}
254			if seen[id] {
255				return fmt.Errorf("%w: %s", ErrDuplicateDevice, id)
256			}
257			seen[id] = true
258		}
259		if spec.BatchSize <= 0 {
260			return ErrInvalidBatchSize
261		}
262		if !spec.WindowStart.Before(spec.WindowEnd) {
263			return ErrInvalidWindow
264		}
265		if !spec.Deadline.After(spec.CreatedAt) {
266			return ErrInvalidDeadline
267		}
268		if spec.TargetVersion == "" {
269			return ErrInvalidVersion
270		}
271		if _, ok := s.versions[spec.TargetVersion]; !ok {
272			return fmt.Errorf("%w: %s", ErrVersionNotFound, spec.TargetVersion)
273		}
274		if _, ok := s.campaigns[spec.ID]; ok {
275			return fmt.Errorf("%w: %s", ErrCampaignExists, spec.ID)
276		}
277		ver := s.versions[spec.TargetVersion]
278		devs := make([]*campaignDevice, 0, len(spec.Devices))
279		for i, id := range spec.Devices {
280			d, ok := s.devices[id]
281			if !ok {
282				return fmt.Errorf("%w: %s", ErrDeviceNotFound, id)
283			}
284			if !containsString(ver.AllowedFrom, d.Version) {
285				return fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, id, d.Version)
286			}
287			if s.deviceBusy(id, spec.ID) {
288				return fmt.Errorf("%w: %s", ErrDeviceBusy, id)
289			}
290			devs = append(devs, &campaignDevice{
291				DeviceID: id,
292				Batch:    i / spec.BatchSize,
293				Status:   DevicePending,
294				Phase:    StageDownload,
295				Download: opState{ID: operationID(spec.ID, id, StageDownload)},
296				Install:  opState{ID: operationID(spec.ID, id, StageInstall)},
297				Rollback: opState{ID: operationID(spec.ID, id, StageRollback)},
298			})
299		}
300		campaign := &campaignState{
301			ID:                spec.ID,
302			Operator:          spec.Operator,
303			Target:            spec.TargetVersion,
304			CreatedAt:         spec.CreatedAt,
305			BatchSize:         spec.BatchSize,
306			WindowStart:       spec.WindowStart,
307			WindowEnd:         spec.WindowEnd,
308			Deadline:          spec.Deadline,
309			RollbackOnFailure: spec.RollbackOnFailure,
310			Devices:           devs,
311			index:             make(map[string]int, len(devs)),
312			LastTime:          spec.CreatedAt,
313			Status:            CampaignRunning,
314		}
315		for i, cd := range devs {
316			campaign.index[cd.DeviceID] = i
317		}
318		return s.commit(func() error {
319			s.campaigns[spec.ID] = campaign
320			return nil
321		})
322	}
323	
324	// deviceBusy 判断设备是否已参加另一个尚未结束的活动。
325	func (s *Store) deviceBusy(deviceID, excludeCampaign string) bool {
326		for id, c := range s.campaigns {
327			if id == excludeCampaign || c.Ended {
328				continue
329			}
330			if _, ok := c.index[deviceID]; ok {
331				return true
332			}
333		}
334		return false
335	}
336	
337	func operationID(campaignID, deviceID, stage string) string {
338		return campaignID + ":" + deviceID + ":" + stage
339	}
340	
341	func containsString(list []string, v string) bool {
342		for _, x := range list {
343			if x == v {
344				return true
345			}
346		}
347		return false
348	}
349	
350	// Claim 由调用方传入当前时间，为活动中的设备领取当前可执行的操作。
351	//
352	// 派发新的下载或安装操作要求设备在线、当前时间位于维护窗口 [start, end) 内、
353	// 所在批次已被前一批全部成功放行。首次领取下载前会再次核对设备当前版本，
354	// 不兼容则将该设备（带阶段、原因和时间）记为失败，返回 ErrIncompatibleVersion；
355	// 开启回滚的活动还会在首次领取下载时把设备当时的当前版本锁定为回滚目标，
356	// 后续普通上报不改变它。
357	// 开启回滚且安装失败已被接受后，设备领取回滚操作：首次领取同样要求设备在线
358	// 且时间位于原维护窗口 [start, end) 内（不受批次放行影响），返回的操作带锁定
359	// 目标版本；离线或窗口外保留待办。回滚已领取但未完成时再次查询返回同一标识，
360	// 且可在窗口外、截止前提交结果。
361	// 已领取但未完成的操作（下载/安装/回滚）再次查询时返回同一标识，不要求在线或位于窗口内。
362	// 离线设备保留待办；离线或窗口外暂无可领取的新操作时返回 (nil, nil)。
363	// 时间缺失或相对本活动已接受的时间倒退时拒绝，且不改变状态。
364	func (s *Store) Claim(campaignID, deviceID string, at time.Time) (*Operation, error) {
365		s.mu.Lock()
366		defer s.mu.Unlock()
367		if err := s.checkOpen(); err != nil {
368			return nil, err
369		}
370		c, cd, err := s.lookupCampaignDevice(campaignID, deviceID)
371		if err != nil {
372			return nil, err
373		}
374		if at.IsZero() {
375			return nil, ErrInvalidTime
376		}
377		if at.Before(c.LastTime) {
378			return nil, fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
379		}
380		var op *Operation
381		var reject error
382		err = s.commit(func() error {
383			// 到达截止时间：未结束设备全部超时并落盘，本次领取拒绝。
384			// 即使查询的设备已有终态，其他未结束设备仍要级联超时。
385			if !at.Before(c.Deadline) {
386				c.LastTime = at
387				s.applyTimeout(c, at)
388				reject = ErrCampaignEnded
389				return nil
390			}
391			if c.Ended {
392				// 纯拒绝路径：不推进时间基线，不改状态。
393				reject = ErrCampaignEnded
394				return nil
395			}
396			if isTerminal(cd.Status) {
397				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, deviceID)
398				return nil
399			}
400			c.LastTime = at
401			// 已领取但未完成的操作：查询仍返回原标识，不要求在线或位于窗口内。
402			if out := outstandingOp(c, cd); out != nil {
403				op = out
404				return nil
405			}
406			// 安装失败已接受、等待回滚：回滚是该设备的善后操作，不受批次放行影响。
407			// 首次领取要求在线且位于原维护窗口 [start,end) 内；离线或窗口外保留待办。
408			if cd.Status == DeviceAwaitingRollback {
409				if !s.devices[deviceID].Online {
410					return nil
411				}
412				if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
413					return nil
414				}
415				cd.Rollback.Claimed = true
416				cd.Rollback.ClaimedAt = at
417				cd.Status = DeviceRollingBack
418				cd.Phase = StageRollback
419				cd.At = at
420				op = &Operation{
421					ID:            cd.Rollback.ID,
422					CampaignID:    c.ID,
423					DeviceID:      deviceID,
424					Kind:          StageRollback,
425					TargetVersion: cd.RollbackTarget,
426				}
427				return nil
428			}
429			// 尚未领取的新阶段：先看批次是否放行（不放行时无操作可领）。
430			if !s.batchOpen(c, cd) {
431				return nil
432			}
433			if !s.devices[deviceID].Online {
434				return nil // 离线保留待办，上线后继续
435			}
436			if at.Before(c.WindowStart) || !at.Before(c.WindowEnd) {
437				return nil // 窗口外不派发新操作；窗口为 [start, end)
438			}
439			if !cd.Download.Claimed {
440				// 首次领取下载前再次检查当前版本。
441				current := s.devices[deviceID].Version
442				if !containsString(s.versions[c.Target].AllowedFrom, current) {
443					reason := fmt.Sprintf("version %s is not compatible with target %s", current, c.Target)
444					// 该设备在下载阶段失败：领取即触发，记录阶段、原因和时间。
445					cd.Download.Claimed = true
446					cd.Download.ClaimedAt = at
447					cd.Download.HasResult = true
448					cd.Download.Success = false
449					cd.Download.Reason = reason
450					cd.Download.At = at
451					s.failDevice(c, cd, StageDownload, reason, at)
452					reject = fmt.Errorf("%w: device %s version %s", ErrIncompatibleVersion, deviceID, current)
453					return nil
454				}
455				// 开启回滚时，把首次领取下载时设备的当前版本锁定为回滚目标；
456				// 此后普通上报不改变它，也不要求该版本另行登记为升级目标。
457				if c.RollbackOnFailure && cd.RollbackTarget == "" {
458					cd.RollbackTarget = current
459				}
460				cd.Download.Claimed = true
461				cd.Download.ClaimedAt = at
462				cd.Status = DeviceDownloading
463				cd.At = at
464				op = &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageDownload}
465				return nil
466			}
467			// 下载已成功：领取安装（尚未领取的安装仍须在线且位于窗口内）。
468			cd.Install.Claimed = true
469			cd.Install.ClaimedAt = at
470			cd.Status = DeviceInstalling
471			cd.At = at
472			op = &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: deviceID, Kind: StageInstall}
473			return nil
474		})
475		if err != nil {
476			return nil, err
477		}
478		if reject != nil {
479			return nil, reject
480		}
481		return op, nil
482	}
483	
484	// outstandingOp 返回设备已领取但尚无结果的操作；没有则返回 nil。
485	func outstandingOp(c *campaignState, cd *campaignDevice) *Operation {
486		switch {
487		case cd.Download.Claimed && !cd.Download.HasResult:
488			return &Operation{ID: cd.Download.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageDownload}
489		case cd.Install.Claimed && !cd.Install.HasResult:
490			return &Operation{ID: cd.Install.ID, CampaignID: c.ID, DeviceID: cd.DeviceID, Kind: StageInstall}
491		case cd.Rollback.Claimed && !cd.Rollback.HasResult:
492			// 已领取但未完成的回滚再次领取仍返回同一标识，并继续告知恢复目标版本。
493			return &Operation{
494				ID:            cd.Rollback.ID,
495				CampaignID:    c.ID,
496				DeviceID:      cd.DeviceID,
497				Kind:          StageRollback,
498				TargetVersion: cd.RollbackTarget,
499			}
500		default:
501			return nil
502		}
503	}
504	
505	// batchOpen 判断设备所在批次是否已放行：前序所有设备必须全部成功。
506	func (s *Store) batchOpen(c *campaignState, cd *campaignDevice) bool {
507		for _, other := range c.Devices {
508			if other.Batch < cd.Batch && other.Status != DeviceSucceeded {
509				return false
510			}
511		}
512		return true
513	}
514	
515	// SubmitResult 接收设备提交的操作结果。
516	//
517	// 相同操作的相同结果重复提交返回成功，但不增加历史、不重复放行批次；
518	// 改用不同结果、跳过未领取阶段、提交未领取的回滚、提交其他设备的操作、
519	// 活动结束后的新结果均报错且不改变状态；已接受结果的重复提交在活动结束后仍有效。
520	// 下载完成后才能领取并安装；设备失败记录阶段、原因和时间，同批其他设备
521	// 继续完成，后续批次记为未执行。安装成功须附带版本等于目标版本的合规上报，
522	// 回滚成功须附带版本等于锁定回滚目标的合规上报，影子与活动在同一次持久化中更新。
523	// 开启回滚的活动中，安装失败不直接结束设备，而是保留原失败原因与时间、
524	// 令设备等待回滚；回滚失败必须给出原因，设备以回滚失败结束且影子不变。
525	// 已领取且尚未接受结果的操作在截止时刻及以后提交时，结果已经迟到：
526	// 不校验附带上报与失败原因、不接收为操作结果，直接按截止处理——未结束设备
527	// 全部超时（等待或正在回滚的记回滚超时），活动以失败结束，返回 ErrCampaignEnded。
528	// 普通设备上报不经过本方法，也不会推进活动。
529	func (s *Store) SubmitResult(res OperationResult) error {
530		s.mu.Lock()
531		defer s.mu.Unlock()
532		if err := s.checkOpen(); err != nil {
533			return err
534		}
535		c, cd, err := s.lookupCampaignDevice(res.CampaignID, res.DeviceID)
536		if err != nil {
537			return err
538		}
539		if res.At.IsZero() {
540			return ErrInvalidTime
541		}
542		// 定位操作标识所属阶段；不属于本设备的操作一律视为未知。
543		var stage string
544		var op *opState
545		switch res.OperationID {
546		case cd.Download.ID:
547			stage, op = StageDownload, &cd.Download
548		case cd.Install.ID:
549			stage, op = StageInstall, &cd.Install
550		case cd.Rollback.ID:
551			stage, op = StageRollback, &cd.Rollback
552		default:
553			return fmt.Errorf("%w: %s", ErrOperationNotFound, res.OperationID)
554		}
555		// 已接受结果：相同结果幂等（活动结束后仍有效，不增加历史、不重复放行），
556		// 不推进时间基线；不同结果冲突。均不改变状态。
557		if op.HasResult {
558			if resultMatches(op, res) {
559				return nil
560			}
561			return fmt.Errorf("%w: operation %s", ErrResultConflict, res.OperationID)
562		}
563		if res.At.Before(c.LastTime) {
564			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, res.At, c.LastTime)
565		}
566		if !op.Claimed {
567			// 标识是本设备未来阶段的操作但尚未领取：属于跳过阶段（含未领取的回滚）。
568			return fmt.Errorf("%w: %s", ErrOperationNotClaimed, res.OperationID)
569		}
570		// 已领取且尚未接受结果的操作在截止时刻及以后提交：结果已经迟到，
571		// 不再接收为操作结果，也不校验附带上报或失败原因——直接按截止处理：
572		// 未结束设备全部超时（等待/正在回滚的记回滚超时），活动以失败结束，
573		// 状态时间与活动结束时间采用本次提交时间，返回 ErrCampaignEnded。
574		// 活动可能已被显式推进到截止而结束：applyTimeout 对已结束活动是空操作，
575		// 结果仍按截止拒绝，不能因附带配置非法或缺少原因改成相应的校验错误。
576		if !res.At.Before(c.Deadline) {
577			if err := s.commit(func() error {
578				c.LastTime = res.At
579				s.applyTimeout(c, res.At)
580				return nil
581			}); err != nil {
582				return err
583			}
584			return ErrCampaignEnded
585		}
586		if !res.Success && res.Reason == "" {
587			return ErrInvalidReason
588		}
589		// 安装/回滚成功附带的设备上报与普通 Report 共用 checkReport 的同一套
590		// 规则（必填字段、版本约束、序号过旧/重复/冲突）；这里先校验并记下判定，
591		// 实际写入在下面的同一次 commit 内与活动、历史一起完成。附带上报任何
592		// 不合规都映射为 ErrInvalidReport，不改成普通上报的错误类别。
593		var repIn reportInput
594		var repCfg json.RawMessage
595		var repVerdict reportVerdict
596		if res.Success && (stage == StageInstall || stage == StageRollback) {
597			// 安装上报版本必须等于升级目标；回滚上报版本必须等于锁定的回滚目标。
598			wantVersion := c.Target
599			if stage == StageRollback {
600				wantVersion = cd.RollbackTarget
601			}
602			repIn = reportInput{
603				DeviceID: res.DeviceID,
604				Seq:      res.Seq,
605				At:       res.At,
606				Version:  res.Version,
607				Config:   res.Config,
608			}
609			var checkErr error
610			repCfg, repVerdict, checkErr = checkReport(s.devices[res.DeviceID], repIn, wantVersion)
611			if checkErr != nil {
612				return reportAttachedError(checkErr.(errBadReport))
613			}
614		}
615		var reject error
616		err = s.commit(func() error {
617			// 活动已结束且提交时间越过截止时间：只推进时间基线并拒绝
618			// （未结束活动的截止处理已在提交前完成，不会到达这里）。
619			if !res.At.Before(c.Deadline) {
620				c.LastTime = res.At
621				s.applyTimeout(c, res.At)
622				reject = ErrCampaignEnded
623				return nil
624			}
625			if c.Ended {
626				// 活动结束后的新结果：拒绝且不改状态（重复结果已在提交前处理）。
627				reject = ErrCampaignEnded
628				return nil
629			}
630			if isTerminal(cd.Status) {
631				reject = fmt.Errorf("%w: %s", ErrDeviceFinished, res.DeviceID)
632				return nil
633			}
634			c.LastTime = res.At
635			op.HasResult = true
636			op.Success = res.Success
637			op.Reason = res.Reason
638			op.At = res.At
639			if !res.Success {
640				switch {
641				case stage == StageInstall && c.RollbackOnFailure:
642					// 安装失败：保留原因和时间，设备转入等待回滚（非终态）；
643					// 同批其他设备继续，后续批次立即记为未执行，活动暂不结束。
644					s.enterRollback(c, cd, res.Reason, res.At)
645				case stage == StageRollback:
646					// 回滚失败必须给出原因：设备以回滚失败结束且影子不变。
647					s.finishRollbackFailure(c, cd, res.Reason, res.At)
648				default:
649					s.failDevice(c, cd, stage, res.Reason, res.At)
650				}
651				return nil
652			}
653			switch stage {
654			case StageDownload:
655				cd.Status = DeviceReady
656				cd.Phase = StageInstall
657				cd.Reason = ""
658				cd.At = res.At
659			case StageInstall:
660				// 安装成功：附带上报与活动同时更新、一起持久化。
661				// 同序号的完全重复上报不重新写入影子（不刷新在线状态与差异时间）。
662				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
663				op.ResultSeq = res.Seq
664				op.ResultVersion = res.Version
665				op.ResultConfig = cloneRaw(res.Config)
666				cd.Status = DeviceSucceeded
667				cd.Phase = StageInstall
668				cd.Reason = ""
669				cd.At = res.At
670			case StageRollback:
671				// 回滚成功：按上报规则更新影子（版本回到锁定目标），同时推进回滚状态。
672				// 期望配置、修订号与审计保持不变；重复上报不重新写入影子。
673				applyReport(s.devices[cd.DeviceID], repIn, repCfg, repVerdict, res.At)
674				op.ResultSeq = res.Seq
675				op.ResultVersion = res.Version
676				op.ResultConfig = cloneRaw(res.Config)
677				cd.Status = DeviceRollbackSucceeded
678				cd.Phase = StageRollback
679				cd.Reason = ""
680				cd.At = res.At
681			}
682			c.Results = append(c.Results, ResultRecord{
683				DeviceID:    cd.DeviceID,
684				OperationID: op.ID,
685				Stage:       stage,
686				Success:     true,
687				Version:     op.ResultVersion,
688				At:          res.At,
689			})
690			s.settle(c, res.At)
691			return nil
692		})
693		if err != nil {
694			return err
695		}
696		return reject
697	}
698	
699	// resultMatches 判断提交是否为已接受结果的重复提交（同一操作、相同结果）。
700	// 安装成功结果还须附带相同的上报（序号、版本、配置）；发生时间不参与判定，
701	// 使活动结束后的重复提交仍然有效。
702	func resultMatches(op *opState, res OperationResult) bool {
703		if op.Success != res.Success || op.Reason != res.Reason {
704			return false
705		}
706		if op.Success && op.ResultSeq != 0 {
707			return op.ResultSeq == res.Seq &&
708				op.ResultVersion == res.Version &&
709				rawEqual(op.ResultConfig, res.Config)
710		}
711		return true
712	}
713	
714	// enterRollback 在开启回滚的活动中处理已接受的安装失败：
715	// 保留原安装失败的原因与时间，令设备等待回滚（非终态）；
716	// 同批其他设备可继续，后续批次立即记为未执行，但活动暂不结束。
717	func (s *Store) enterRollback(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
718		cd.Status = DeviceAwaitingRollback
719		cd.Phase = StageRollback
720		cd.Reason = reason
721		cd.At = at
722		c.Results = append(c.Results, ResultRecord{
723			DeviceID:    cd.DeviceID,
724			OperationID: cd.Install.ID,
725			Stage:       StageInstall,
726			Success:     false,
727			Reason:      reason,
728			At:          at,
729		})
730		skipLaterBatches(c, cd, at)
731		// 不结束活动：设备进入非终态的等待回滚，活动要等其回滚结束。
732	}
733	
734	// finishRollbackFailure 处理已接受的回滚失败：必须给出原因，
735	// 设备以回滚失败结束，影子不变（失败结果不附带、不应用上报）。
736	func (s *Store) finishRollbackFailure(c *campaignState, cd *campaignDevice, reason string, at time.Time) {
737		cd.Status = DeviceRollbackFailed
738		cd.Phase = StageRollback
739		cd.Reason = reason
740		cd.At = at
741		c.Results = append(c.Results, ResultRecord{
742			DeviceID:    cd.DeviceID,
743			OperationID: cd.Rollback.ID,
744			Stage:       StageRollback,
745			Success:     false,
746			Reason:      reason,
747			At:          at,
748		})
749		s.settle(c, at)
750	}
751	
752	// skipLaterBatches 把后续批次中尚未结束的设备立即记为未执行。
753	func skipLaterBatches(c *campaignState, cd *campaignDevice, at time.Time) {
754		for _, other := range c.Devices {
755			if other.Batch > cd.Batch && !isTerminal(other.Status) {
756				other.Status = DeviceSkipped
757				other.Phase = pendingPhase(other)
758				other.Reason = "not executed: previous batch failed"
759				other.At = at
760			}
761		}
762	}
763	
764	// failDevice 将设备记为失败，记录阶段、原因和时间；后续批次全部记为未执行，
765	// 本批其他设备继续。若全部设备已到终态，则活动以失败结束。
766	func (s *Store) failDevice(c *campaignState, cd *campaignDevice, phase, reason string, at time.Time) {
767		cd.Status = DeviceFailed
768		cd.Phase = phase
769		cd.Reason = reason
770		cd.At = at
771		c.Results = append(c.Results, ResultRecord{
772			DeviceID:    cd.DeviceID,
773			OperationID: opIDFor(cd, phase),
774			Stage:       phase,
775			Success:     false,
776			Reason:      reason,
777			At:          at,
778		})
779		skipLaterBatches(c, cd, at)
780		s.settle(c, at)
781	}
782	
783	func opIDFor(cd *campaignDevice, phase string) string {
784		switch phase {
785		case StageInstall:
786			return cd.Install.ID
787		case StageRollback:
788			return cd.Rollback.ID
789		default:
790			return cd.Download.ID
791		}
792	}
793	
794	// pendingPhase 返回设备尚未完成的阶段：下载成功后停留在安装阶段。
795	func pendingPhase(cd *campaignDevice) string {
796		if cd.Download.HasResult && cd.Download.Success {
797			return StageInstall
798		}
799		return StageDownload
800	}
801	
802	// applyTimeout 在当前时间达到截止时间时，把所有未结束设备记为超时，
803	// 已有终态保持不变，活动记为失败并结束。等待回滚或正在回滚的设备
804	// 以回滚阶段超时结束；不改写或清空影子。
805	func (s *Store) applyTimeout(c *campaignState, at time.Time) {
806		if c.Ended {
807			return
808		}
809		for _, cd := range c.Devices {
810			if isTerminal(cd.Status) {
811				continue
812			}
813			switch cd.Status {
814			case DeviceAwaitingRollback, DeviceRollingBack:
815				cd.Status = DeviceRollbackTimeout
816				cd.Phase = StageRollback
817			default:
818				cd.Status = DeviceTimeout
819				cd.Phase = pendingPhase(cd)
820			}
821			cd.Reason = "deadline exceeded"
822			cd.At = at
823		}
824		c.Status = CampaignFailed
825		c.Ended = true
826		c.EndedAt = at
827	}
828	
829	// settle 在全部设备到达终态时结束活动：全部成功则成功，否则失败。
830	// 即使回滚成功，设备也不是 succeeded，活动仍为失败。
831	func (s *Store) settle(c *campaignState, at time.Time) {
832		allSucceeded := true
833		for _, cd := range c.Devices {
834			if !isTerminal(cd.Status) {
835				return
836			}
837			if cd.Status != DeviceSucceeded {
838				allSucceeded = false
839			}
840		}
841		c.Ended = true
842		c.EndedAt = at
843		if allSucceeded {
844			c.Status = CampaignSucceeded
845		} else {
846			c.Status = CampaignFailed
847		}
848	}
849	
850	func isTerminal(status string) bool {
851		switch status {
852		case DeviceSucceeded, DeviceFailed, DeviceTimeout, DeviceSkipped,
853			DeviceRollbackSucceeded, DeviceRollbackFailed, DeviceRollbackTimeout:
854			return true
855		default:
856			return false
857		}
858	}
859	
860	// AdvanceCampaign 用调用方给出的当前时间推进活动：到达截止时间时把未结束
861	// 设备全部记为超时并结束活动。时间缺失或相对已接受时间倒退时拒绝且不改状态。
862	// 未到截止时间或活动已结束时为空操作。
863	func (s *Store) AdvanceCampaign(campaignID string, at time.Time) error {
864		s.mu.Lock()
865		defer s.mu.Unlock()
866		if err := s.checkOpen(); err != nil {
867			return err
868		}
869		c, err := s.lookupCampaign(campaignID)
870		if err != nil {
871			return err
872		}
873		if at.IsZero() {
874			return ErrInvalidTime
875		}
876		if at.Before(c.LastTime) {
877			return fmt.Errorf("%w: %v before %v", ErrTimeRegression, at, c.LastTime)
878		}
879		if c.Ended {
880			return nil
881		}
882		if at.Before(c.Deadline) {
883			// 仅推进时间基线也持久化，使重开后的倒退判断仍然有效。
884			return s.commit(func() error { c.LastTime = at; return nil })
885		}
886		return s.commit(func() error {
887			c.LastTime = at
888			s.applyTimeout(c, at)
889			return nil
890		})
891	}
892	
893	func (s *Store) lookupCampaign(campaignID string) (*campaignState, error) {
894		if campaignID == "" {
895			return nil, ErrInvalidCampaignID
896		}
897		c, ok := s.campaigns[campaignID]
898		if !ok {
899			return nil, fmt.Errorf("%w: %s", ErrCampaignNotFound, campaignID)
900		}
901		return c, nil
902	}
903	
904	func (s *Store) lookupCampaignDevice(campaignID, deviceID string) (*campaignState, *campaignDevice, error) {
905		c, err := s.lookupCampaign(campaignID)
906		if err != nil {
907			return nil, nil, err
908		}
909		if deviceID == "" {
910			return nil, nil, ErrInvalidDeviceID
911		}
912		i, ok := c.index[deviceID]
913		if !ok {
914			return nil, nil, fmt.Errorf("%w: %s", ErrDeviceNotInCampaign, deviceID)
915		}
916		return c, c.Devices[i], nil
917	}
918	
919	// DeviceStatusView 是一台设备在活动中的状态快照。
920	type DeviceStatusView struct {
921		DeviceID string
922		Batch    int
923		// Status 取 Device* 状态常量，含等待回滚、正在回滚、回滚成功、
924		// 回滚失败与回滚阶段超时。
925		Status string
926		// Phase 是设备当前停留或失败的阶段（download/install/rollback）。
927		Phase string
928		// Reason 是失败、超时或未执行（skipped）的原因；成功时为空。
929		Reason string
930		// At 是进入当前状态的时间。
931		At time.Time
932		// DownloadID/InstallID/RollbackID 是各阶段操作的稳定标识。
933		DownloadID string
934		InstallID  string
935		RollbackID string
936		// RollbackTarget 是开启回滚时首次领取下载锁定的回滚目标版本；未锁定为空。
937		RollbackTarget string
938		// InstallFailReason/InstallFailAt 是已接受的安装失败的原因与时间，
939		// 进入回滚后仍保留原值，便于与回滚结果分别查看。
940		InstallFailReason string
941		InstallFailAt     time.Time
942		// RollbackResult 表示是否已接受回滚结果。
943		RollbackResult bool
944		// RollbackSuccess 表示已接受的回滚结果是否成功。
945		RollbackSuccess bool
946		// RollbackReason/RollbackAt 是回滚结果（成功或失败）的原因与时间。
947		RollbackReason string
948		RollbackAt     time.Time
949	}
950	
951	// BatchView 是一个批次内所有设备的状态，按提交次序排列。
952	type BatchView struct {
953		Index   int
954		Devices []DeviceStatusView
955	}
956	
957	// CampaignView 是分批升级活动的只读快照。
958	type CampaignView struct {
959		ID            string
960		Operator      string
961		TargetVersion string
962		CreatedAt     time.Time
963		BatchSize     int
964		WindowStart   time.Time
965		WindowEnd     time.Time
966		Deadline      time.Time
967		// RollbackOnFailure 表示该活动是否开启安装失败回滚。
968		RollbackOnFailure bool
969		// Status 取 Campaign* 状态常量。
970		Status  string
971		Ended   bool
972		EndedAt time.Time
973		// Devices 按提交次序给出每台设备的状态。
974		Devices []DeviceStatusView
975		// Batches 按批次号分组，保留设备提交次序。
976		Batches []BatchView
977		// Results 是按接受顺序排列的结果历史（重复提交不产生新记录）。
978		Results []ResultRecord
979	}
980	
981	// GetCampaign 查询活动：创建者、目标版本、每批设备状态、
982	// 失败或超时原因及结果历史。返回数据为独立副本。
983	func (s *Store) GetCampaign(campaignID string) (CampaignView, error) {
984		s.mu.Lock()
985		defer s.mu.Unlock()
986		if err := s.checkOpen(); err != nil {
987			return CampaignView{}, err
988		}
989		c, err := s.lookupCampaign(campaignID)
990		if err != nil {
991			return CampaignView{}, err
992		}
993		v := CampaignView{
994			ID:                c.ID,
995			Operator:          c.Operator,
996			TargetVersion:     c.Target,
997			CreatedAt:         c.CreatedAt,
998			BatchSize:         c.BatchSize,
999			WindowStart:       c.WindowStart,
1000			WindowEnd:         c.WindowEnd,
1001			Deadline:          c.Deadline,
1002			RollbackOnFailure: c.RollbackOnFailure,
1003			Status:            c.Status,
1004			Ended:             c.Ended,
1005			EndedAt:           c.EndedAt,
1006			Results:           make([]ResultRecord, len(c.Results)),
1007		}
1008		copy(v.Results, c.Results)
1009		for _, cd := range c.Devices {
1010			dv := DeviceStatusView{
1011				DeviceID:       cd.DeviceID,
1012				Batch:          cd.Batch,
1013				Status:         cd.Status,
1014				Phase:          cd.Phase,
1015				Reason:         cd.Reason,
1016				At:             cd.At,
1017				DownloadID:     cd.Download.ID,
1018				InstallID:      cd.Install.ID,
1019				RollbackID:     cd.Rollback.ID,
1020				RollbackTarget: cd.RollbackTarget,
1021			}
1022			// 安装失败原因与时间独立保留，进入回滚后也不被回滚结果覆盖。
1023			if cd.Install.HasResult && !cd.Install.Success {
1024				dv.InstallFailReason = cd.Install.Reason
1025				dv.InstallFailAt = cd.Install.At
1026			}
1027			// 回滚结果的原因与时间单独呈现。
1028			if cd.Rollback.HasResult {
1029				dv.RollbackResult = true
1030				dv.RollbackSuccess = cd.Rollback.Success
1031				dv.RollbackReason = cd.Rollback.Reason
1032				dv.RollbackAt = cd.Rollback.At
1033			}
1034			v.Devices = append(v.Devices, dv)
1035			for len(v.Batches) <= cd.Batch {
1036				v.Batches = append(v.Batches, BatchView{Index: len(v.Batches)})
1037			}
1038			v.Batches[cd.Batch].Devices = append(v.Batches[cd.Batch].Devices, dv)
1039		}
1040		return v, nil
1041	}
1042	
1043	// DeviceWork 是设备当前版本与待执行操作的查询结果。
1044	type DeviceWork struct {
1045		DeviceID string
1046		Version  string
1047		Online   bool
1048		// CampaignID 是设备当前所在的未结束活动；没有时为空。
1049		CampaignID string
1050		// Pending 是设备仍待完成的操作（至多一个）：已领取未完成或下一阶段可领取。
1051		// 等待回滚时为尚未领取的回滚操作，其 TargetVersion 给出锁定的回滚目标。
1052		Pending *Operation
1053		// PendingClaimed 表示 Pending 是否已领取（未领取的安装或回滚仍须等维护窗口）。
1054		PendingClaimed bool
1055	}
1056	
1057	// GetDeviceWork 查询设备当前版本及其待执行操作。
1058	func (s *Store) GetDeviceWork(deviceID string) (DeviceWork, error) {
1059		s.mu.Lock()
1060		defer s.mu.Unlock()
1061		if err := s.checkOpen(); err != nil {
1062			return DeviceWork{}, err
1063		}
1064		d, err := s.lookup(deviceID)
1065		if err != nil {
1066			return DeviceWork{}, err
1067		}
1068		w := DeviceWork{DeviceID: deviceID, Version: d.Version, Online: d.Online}
1069		for id, c := range s.campaigns {
1070			if c.Ended {
1071				continue
1072			}
1073			i, ok := c.index[deviceID]
1074			if !ok {
1075				continue
1076			}
1077			cd := c.Devices[i]
1078			w.CampaignID = id
1079			if out := outstandingOp(c, cd); out != nil {
1080				w.Pending = out
1081				w.PendingClaimed = true
1082			} else if cd.Status == DeviceAwaitingRollback {
1083				// 回滚待领取：显示回滚目标，标记为尚未领取。
1084				w.Pending = &Operation{
1085					ID:            cd.Rollback.ID,
1086					CampaignID:    c.ID,
1087					DeviceID:      deviceID,
1088					Kind:          StageRollback,
1089					TargetVersion: cd.RollbackTarget,
1090				}
1091				w.PendingClaimed = false
1092			} else if !isTerminal(cd.Status) {
1093				kind := StageDownload
1094				id := cd.Download.ID
1095				if cd.Download.HasResult {
1096					kind, id = StageInstall, cd.Install.ID
1097				}
1098				w.Pending = &Operation{ID: id, CampaignID: c.ID, DeviceID: deviceID, Kind: kind}
1099				w.PendingClaimed = false
1100			}
1101			break
1102		}
1103		return w, nil
1104	}
1105	
1106	// ListUpgrades 返回已登记的全部升级目标版本，按目标版本字典序排列。
1107	func (s *Store) ListUpgrades() ([]VersionSpec, error) {
1108		s.mu.Lock()
1109		defer s.mu.Unlock()
1110		if err := s.checkOpen(); err != nil {
1111			return nil, err
1112		}
1113		out := make([]VersionSpec, 0, len(s.versions))
1114		for _, v := range s.versions {
1115			out = append(out, VersionSpec{Target: v.Target, AllowedFrom: append([]string(nil), v.AllowedFrom...)})
1116		}
1117		sort.Slice(out, func(i, j int) bool { return out[i].Target < out[j].Target })
1118		return out, nil
1119	}
