	bringOnline(t, s, "d1")
	bringOnline(t, s, "d2")
	_, failAt := awaitRollback(t, s, spec, "d1", upBase.Add(2*time.Minute))
	rbBefore, _ := s.Claim(spec.ID, "d1", upBase.Add(8*time.Minute)) // 正在回滚
	// d2 停在等待回滚。
	awaitRollback(t, s, spec, "d2", upBase.Add(12*time.Minute))
	if err := s.Close(); err != nil {
		t.Fatal(err)
	}

